#include <stdio.h>
#include <string.h>
#include <stdlib.h>

static int is_matching_pair(char open, char close)
{
    return (open == '(' && close == ')') ||
           (open == '[' && close == ']') ||
           (open == '{' && close == '}');
}

static int is_balanced(const char *s)
{
    size_t len = strlen(s);
    char *stack = (char *)malloc(len);
    if (!stack) return 0;
    size_t top = 0;
    for (size_t i = 0; i < len; ++i) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
        } else if (c == ')' || c == ']' || c == '}') {
            if (top == 0) { free(stack); return 0; }
            char open = stack[--top];
            if (!is_matching_pair(open, c)) { free(stack); return 0; }
        }
    }
    int ok = (top == 0);
    free(stack);
    return ok;
}

int main(int argc, char *argv[])
{
    if (argc < 2) {
        puts("BALANCED");
        return 0;
    }
    if (is_balanced(argv[1]))
        puts("BALANCED");
    else
        puts("UNBALANCED");
    return 0;
}
